//! Intramolecular skip weights, indexed by bond distance.
//!
//! molrs used to own this table as `BondDistanceWeights`. That type is gone:
//! a force field's 1-2/1-3/1-4 exceptions are rows of a frame's `pairs`
//! block, generated by [`molrs::core::Topology::pairs_block`]. Packing still
//! needs a caller-chosen skip table (exempt 1-4, score 1-5, or a coarse-grain
//! depth), so the table lives here. It is not `ForceField::special_bonds`.

use molrs::core::Topology;
use molrs::op::F;

/// Bond-distance scale weights: slot 0 is 1-2, the last slot is the 1-N tail.
///
/// Weights are dimensionless in `[0, 1]`. `0.0` exempts that distance, `1.0`
/// scores it at full strength. [`from_exclusion_depth`](Self::from_exclusion_depth)
/// is "exempt up to this hop, then score the rest".
#[derive(Debug, Clone, PartialEq)]
pub struct BondDistanceWeights(Vec<F>);

impl BondDistanceWeights {
    /// Construct a table from explicit per-distance weights.
    ///
    /// `weights[0]` is bond-distance 1 (1-2). The last entry is the 1-N tail.
    ///
    /// # Errors
    ///
    /// A message when `weights` is empty or any entry is outside `[0, 1]` or
    /// not finite.
    pub fn new(weights: Vec<F>) -> Result<Self, String> {
        if weights.is_empty() {
            return Err("bond-distance weights must be non-empty".to_string());
        }
        for (i, &w) in weights.iter().enumerate() {
            if !(0.0..=1.0).contains(&w) || !w.is_finite() {
                return Err(format!(
                    "bond-distance weight[{i}] = {w} is outside [0, 1] or not finite"
                ));
            }
        }
        Ok(Self(weights))
    }

    /// Exempt bond distances `1..=depth` and set the 1-N tail to `1.0`.
    ///
    /// Depth 3 is `[0, 0, 0, 1]`: 1-2 / 1-3 / 1-4 exempt, 1-5+ scored.
    pub fn from_exclusion_depth(depth: usize) -> Self {
        let mut weights = vec![0.0; depth];
        weights.push(1.0);
        Self(weights)
    }

    /// Scale weight at graph distance `distance`.
    ///
    /// Distance 0 is the atom itself and is always `0.0`. Distances past the
    /// last slot return the 1-N tail.
    pub fn weight(&self, distance: usize) -> F {
        if distance == 0 {
            return 0.0;
        }
        self.0[(distance - 1).min(self.0.len() - 1)]
    }

    /// The stored table: index 0 is 1-2, the last index is the 1-N tail.
    pub fn as_slice(&self) -> &[F] {
        &self.0
    }
}

/// Per-atom partners whose bond-distance weight is exactly `0.0`.
///
/// Each inner list is root-inclusive and sorted ascending. A zero tail walks
/// the whole connected component; otherwise the walk stops at the last
/// distance whose weight is `0`, then keeps partners iff `weight(d) == 0.0`.
pub(crate) fn exclusions(topology: &Topology, weights: &BondDistanceWeights) -> Vec<Vec<usize>> {
    let tail_zero = weights.as_slice().last() == Some(&0.0);
    let cap = if tail_zero {
        None
    } else {
        let mut last_zero = 0usize;
        for d in 1..=weights.as_slice().len() {
            if weights.weight(d) == 0.0 {
                last_zero = d;
            }
        }
        Some(last_zero)
    };
    (0..topology.n_atoms())
        .map(|root| {
            let mut list = Vec::new();
            for (partner, &distance) in topology.distances(root).iter().enumerate() {
                if distance < 0 {
                    continue;
                }
                let distance = distance as usize;
                if cap.is_some_and(|limit| distance > limit) {
                    continue;
                }
                if weights.weight(distance) == 0.0 {
                    list.push(partner);
                }
            }
            list
        })
        .collect()
}
